CREATE TABLE "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE session (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX idx_session_user ON session("userId");
CREATE TABLE account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX account_user ON account("userId");
CREATE TABLE verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX verification_identifier ON verification(identifier);
CREATE TABLE "rateLimit" (id text PRIMARY KEY, key text UNIQUE NOT NULL, count integer NOT NULL, "lastRequest" bigint NOT NULL);
CREATE TABLE profiles (owner_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE, school text NOT NULL DEFAULT '', locale text NOT NULL DEFAULT 'kk' CHECK(locale IN ('kk','ru')), grades jsonb NOT NULL DEFAULT '[]', styles jsonb NOT NULL DEFAULT '{}', deleted_at timestamptz);
CREATE TABLE uploads (id uuid PRIMARY KEY, owner_id text NOT NULL REFERENCES "user"(id), object_key text NOT NULL UNIQUE, original_name text NOT NULL, mime text NOT NULL, bytes bigint NOT NULL CHECK(bytes>0 AND bytes<=26214400), checksum text NOT NULL, scan_status text NOT NULL, status text NOT NULL DEFAULT 'complete', created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE INDEX uploads_owner ON uploads(owner_id,created_at);
CREATE TABLE plans (id uuid PRIMARY KEY, owner_id text NOT NULL REFERENCES "user"(id), file_id uuid REFERENCES uploads(id), title text NOT NULL, grade integer CHECK(grade BETWEEN 1 AND 11), school_year text NOT NULL DEFAULT '', locale text NOT NULL DEFAULT 'kk', status text NOT NULL DEFAULT 'extracting', revision integer NOT NULL DEFAULT 1 CHECK(revision>0), created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE INDEX plans_owner ON plans(owner_id,created_at DESC) WHERE deleted_at IS NULL;
CREATE TABLE plan_versions (id uuid PRIMARY KEY, plan_id uuid NOT NULL REFERENCES plans(id) ON DELETE CASCADE, revision integer NOT NULL, rows jsonb NOT NULL DEFAULT '[]', warnings jsonb NOT NULL DEFAULT '[]', unrecognized jsonb NOT NULL DEFAULT '[]', parser_version text NOT NULL, grade integer, school_year text NOT NULL DEFAULT '', confirmed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(plan_id,revision));
CREATE TABLE generations (id uuid PRIMARY KEY,owner_id text NOT NULL REFERENCES "user"(id), plan_id uuid REFERENCES plans(id), row_id uuid NOT NULL, source_snapshot jsonb NOT NULL, title text NOT NULL, locale text NOT NULL, status text NOT NULL DEFAULT 'queued', revision integer NOT NULL DEFAULT 1, demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE INDEX generations_owner ON generations(owner_id,created_at DESC) WHERE deleted_at IS NULL;
CREATE TABLE generation_versions (id uuid PRIMARY KEY, generation_id uuid NOT NULL REFERENCES generations(id) ON DELETE CASCADE, revision integer NOT NULL, document jsonb NOT NULL, validation jsonb NOT NULL, model text NOT NULL, prompt_version text NOT NULL, usage jsonb NOT NULL DEFAULT '{}', provider_request_id text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(generation_id,revision));
CREATE TABLE exports (id uuid PRIMARY KEY, owner_id text NOT NULL REFERENCES "user"(id),generation_id uuid NOT NULL REFERENCES generations(id),generation_version_id uuid NOT NULL REFERENCES generation_versions(id), format text NOT NULL CHECK(format IN ('docx','pdf')),audience text NOT NULL CHECK(audience IN ('full','student')),styles jsonb NOT NULL,object_key text UNIQUE,status text NOT NULL DEFAULT 'queued',checksum text,renderer_version text,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX exports_owner ON exports(owner_id,created_at DESC) WHERE deleted_at IS NULL;
CREATE TABLE jobs (id uuid PRIMARY KEY,owner_id text NOT NULL REFERENCES "user"(id),kind text NOT NULL CHECK(kind IN ('import','generate','regenerate','export','delete')),resource_id uuid NOT NULL,payload jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','succeeded','failed','cancelled')),stage text NOT NULL DEFAULT 'queued',attempt integer NOT NULL DEFAULT 0,max_attempts integer NOT NULL DEFAULT 3,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token uuid,heartbeat timestamptz,error_code text,result jsonb,cancel_requested boolean NOT NULL DEFAULT false,idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,idempotency_key));
CREATE INDEX jobs_claim ON jobs(available_at,created_at) WHERE status IN ('queued','running');
CREATE INDEX jobs_owner ON jobs(owner_id,created_at DESC);
CREATE TABLE usage_ledger (id uuid PRIMARY KEY,owner_id text NOT NULL REFERENCES "user"(id),job_id uuid NOT NULL UNIQUE REFERENCES jobs(id),state text NOT NULL CHECK(state IN ('reserved','charged','released','uncertain')),tokens integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX usage_daily ON usage_ledger(owner_id,created_at);
CREATE TABLE audit (id uuid PRIMARY KEY,owner_id text,action text NOT NULL,resource_id uuid,request_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE api_limits (key text NOT NULL,window_start timestamptz NOT NULL,count integer NOT NULL,PRIMARY KEY(key,window_start));
CREATE TABLE worker_health (id text PRIMARY KEY,heartbeat timestamptz NOT NULL);
